<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>用户管理</h1><p>管理平台普通用户，不包含比赛专用账号。</p></div><div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button><el-button type="primary" icon="el-icon-plus" @click="openCreate">新增用户</el-button></div></header><div class="course-filters"><el-input v-model="keyword" prefix-icon="el-icon-search" clearable placeholder="按用户名搜索" /></div><div class="module-table-wrap"><el-table v-loading="loading" :data="filtered" empty-text="暂无平台用户"><el-table-column prop="userName" label="用户名" min-width="180" /><el-table-column prop="userId" label="用户编号" width="100" /><el-table-column prop="role" label="角色" width="120" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.enabled===false?'danger':'success'">{{ s.row.enabled===false?'停用':'启用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template slot-scope="s"><el-button size="small" @click="openEdit(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog :title="editing?'编辑用户':'新增平台用户'" :visible.sync="dialog" width="460px"><el-form :model="form" label-width="90px"><el-form-item label="用户名"><el-input v-model="form.userName" /></el-form-item><el-form-item label="密码"><el-input v-model="form.password" show-password placeholder="编辑时留空表示不修改" /></el-form-item><el-form-item v-if="editing" label="启用状态"><el-switch v-model="form.enabled" /></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></span></el-dialog></section></template>
<script>
import request from '@/utils/request'
import { createAdminUserApi, updateAdminUserApi } from '@/api/Match'
export default { data:()=>({loading:false,saving:false,dialog:false,editing:false,users:[],keyword:'',form:{userName:'',password:'',enabled:true,userId:null}}),computed:{filtered(){return this.users.filter(u=>!this.keyword||String(u.userName||u.username||'').toLowerCase().includes(this.keyword.toLowerCase()))}},created(){this.load()},methods:{async load(){this.loading=true;try{const r=await request.get('/admin/users');this.users=r.data||[]}finally{this.loading=false}},openCreate(){this.editing=false;this.form={userName:'',password:'',enabled:true,userId:null};this.dialog=true},openEdit(user){this.editing=true;this.form={userId:user.userId,userName:user.userName||user.username,password:'',enabled:user.enabled!==false};this.dialog=true},async save(){if(!this.form.userName||(!this.editing&&!this.form.password)){this.$message.error('用户名和密码不能为空');return}this.saving=true;try{if(this.editing){const payload={userName:this.form.userName,enabled:this.form.enabled};if(this.form.password)payload.password=this.form.password;await updateAdminUserApi(this.form.userId,payload)}else await createAdminUserApi(this.form);this.dialog=false;await this.load()}finally{this.saving=false}}} }
</script>
